export function slugify(input, options = {}) {
  const separator = options.separator ?? "-";
  if (typeof separator !== "string" || separator.length === 0) {
    throw new TypeError("options.separator must be a non-empty string");
  }

  const { maxLength } = options;
  if (
    maxLength !== undefined &&
    !(Number.isInteger(maxLength) && maxLength > 0)
  ) {
    throw new TypeError("options.maxLength must be a positive integer");
  }

  const normalized = String(input)
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase();

  const slug = normalized
    .replace(/[^\p{L}\p{N}]+/gu, separator)
    .split(separator)
    .filter(Boolean)
    .join(separator);

  if (maxLength === undefined || slug.length <= maxLength) {
    return slug;
  }

  let truncated = slug.slice(0, maxLength);
  const boundary = truncated.lastIndexOf(separator);
  if (boundary > 0) {
    truncated = truncated.slice(0, boundary);
  }

  while (truncated.endsWith(separator)) {
    truncated = truncated.slice(0, -separator.length);
  }

  return truncated;
}
